pub fn rgb565(r:u8,g:u8,b:u8)->u16{((r as u16>>3)<<11)|((g as u16>>2)<<5)|(b as u16>>3)} pub fn rle565(p:&[u16])->Vec<u8>{let mut o=Vec::new();let mut i=0;while i<p.len(){let v=p[i];let mut n=1;while i+n<p.len()&&p[i+n]==v&&n<255{n+=1}o.push(n as u8);o.extend(v.to_le_bytes());i+=n}o} pub fn tilemap_csv(s:&str)->Result<Vec<u16>,String>{s.replace('\n',",").split(',').filter(|x|!x.trim().is_empty()).map(|x|x.trim().parse().map_err(|_|"bad tile".into())).collect()}
